import { NavLink, Outlet } from 'react-router-dom'
import { clsx } from 'clsx'

const SETTINGS_TABS = [
  { path: '/settings/account', label: 'Account' },
  { path: '/settings/appearance', label: 'Appearance' },
  { path: '/settings/language', label: 'Language' },
  { path: '/settings/skills', label: 'Skills' },
  { path: '/settings/notifications', label: 'Notifications' },
  { path: '/settings/security', label: 'Security' },
]

export function SettingsLayout() {
  return (
    <div className="flex h-full overflow-hidden">
      <aside className="w-44 flex-shrink-0 border-r border-border bg-surface flex flex-col overflow-y-auto">
        <div className="px-3 py-4 border-b border-border">
          <span className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">Settings</span>
        </div>
        {SETTINGS_TABS.map((tab) => (
          <NavLink key={tab.path} to={tab.path}
            className={({ isActive }) => clsx('px-3 py-2 text-sm mx-1 my-0.5 rounded-lg transition-colors',
              isActive ? 'bg-accent/10 text-accent font-medium' : 'text-muted-foreground hover:text-foreground hover:bg-muted')}>
            {tab.label}
          </NavLink>
        ))}
      </aside>
      <div className="flex-1 overflow-hidden"><Outlet /></div>
    </div>
  )
}
